<template>
  <SafetyManagementShell title="每日安全生产检查记录" subtitle="七类检查汇总 · 每天一份 · 三类人员签认方式待定">
    <view class="sm-stack">
      <view class="sm-card"><view class="sm-section-head"><view class="sm-row"><text class="sm-h2">日管控</text><picker mode="date" :value="selectedDate" @change="changeDate($event.detail.value)"><view class="sm-picker">{{ selectedDate }} ▾</view></picker></view><text class="sm-tag sm-tag--warn">待签认</text></view><text class="sm-help">日期按北京时间、实际巡查完成日归属。多次巡查分别保留时段，后一次正常不覆盖前一次问题。</text></view>
      <view v-if="loading" class="sm-state">正在汇总当天全部原记录…</view>
      <view v-else-if="error" class="sm-alert sm-alert--error">{{ error }}<button class="sm-btn sm-btn--secondary" @click="load">重新加载</button></view>
      <template v-else>

        <view v-if="daily.stale" class="sm-alert">当天新增巡检、补充或关联资料已有变化。原核对版本保留，请检查变化后重新核对。</view>
        <view v-if="!permissions.daily" class="sm-alert sm-alert--info">本巡检本人可在巡检流程录入七类事实；核对日表仍须配置本厂站安全员。岗位账号、启用日期及签字方式尚未设置时，不自动视为已核对或签认。</view>
        <view class="sm-tabs"><view v-for="tab in tabs" :key="tab.key" :class="['sm-tab',{'sm-tab--active':activeTab===tab.key}]" @click="activeTab=tab.key">{{ tab.label }}</view></view>
        <view v-show="activeTab==='sources'" class="sm-stack">
          <view class="sm-card"><view class="sm-section-head"><text class="sm-h2">当天巡检 · {{ snapshot.inspections?.length || 0 }} 次</text><button class="sm-btn sm-btn--secondary sm-btn--small" @click="openPage('/pages/station-safety-inspection/form')">新增巡检</button></view><text v-if="!snapshot.inspections?.length" class="sm-alert">尚无当天巡检记录。补充可以暂存，日表不能据此认定完整。</text><view v-for="inspection in snapshot.inspections" :key="inspection._id" class="sm-list-row"><view class="sm-section-head"><text class="sm-h3">{{ inspection.inspection_no }}</text><view class="sm-row"><text class="sm-link" @click="continueWorkflow(inspection._id)">继续七类核对</text><text class="sm-link" @click="openInspection(inspection._id)">查看原单及照片</text></view></view><text class="sm-text">{{ inspection.inspector_name }} · {{ inspection.weather || '天气未记录' }}</text><text class="sm-help">实际巡查：{{ formatDateTime(inspection.started_at) }} 至 {{ formatDateTime(inspection.ended_at) }}</text><text class="sm-help">系统提交：{{ formatDateTime(inspection.submitted_at || inspection.created_at) }} · 原单版本 {{ inspection.revision || 1 }} · {{ inspection.abnormal_count || 0 }} 项异常</text></view></view>
          <view v-for="category in snapshot.categories" :key="category.id" class="sm-card"><view class="sm-section-head"><text class="sm-h2">{{ category.id }}．{{ category.name }}</text></view><text class="sm-text sm-help">{{ categoryProgressText(category) }}</text><view v-if="categoryPending(category).length" class="sm-alert"><text class="sm-h3">本类待办</text><view v-for="(pending,pendingIndex) in categoryPending(category)" :key="pendingIndex" class="sm-list-row"><text class="sm-text">{{ pending.label }}：{{ (pending.messages || []).join('；') }}</text><button class="sm-btn sm-btn--secondary sm-btn--small" @click="continueWorkflow(pending.inspection_id,category.id)">去巡检中填写</button></view></view><view v-for="(check,index) in category.checks" :key="`${check.source_id}-${check.item_code}-${index}`" class="sm-list-row"><view class="sm-row"><text :class="['sm-tag',check.result_code==='abnormal'?'sm-tag--bad':check.result_code==='normal' && !check.missing?.length?'sm-tag--good':'sm-tag--warn']">{{ checkStatus(check) }}</text><text class="sm-h3">{{ check.label }}</text></view><text v-if="check.note" class="sm-text">{{ check.note }}</text><text v-if="check.detail_text" class="sm-help">{{ check.detail_text }}</text><text v-if="check.observed_at" class="sm-help">事实截至：{{ formatDateTime(check.observed_at) }}</text><text class="sm-help">{{ ['supplement','inspection_workflow'].includes(check.source_type)?'巡检七类核对':check.covered_by_inspection?'原巡检覆盖引用':'原巡检' }} · {{ check.item_code }}<template v-if="check.related_categories?.length"> · 同一证据同时支持第 {{ check.related_categories.join('、') }} 类</template></text><text v-if="check.hazard_ids?.length" class="sm-help">关联隐患：{{ check.hazard_ids.join('、') }}</text></view><text v-if="!category.checks?.length" class="sm-help">尚无检查事实引用，不能自动判为正常。</text></view>
        </view>
        <view v-show="activeTab==='supplement'" class="sm-stack">
          <view class="sm-card"><text class="sm-h2">在对应巡检中补齐七类事实</text><text class="sm-help">每次巡检保留自己的事实截至时间。原检查、适用作业和问题自动汇入当天日表；后续正常不会覆盖前次问题。</text><picker v-if="inspectionOptions.length" :range="inspectionOptions" range-key="label" :value="inspectionIndex" @change="chooseInspection(Number($event.detail.value))"><view class="sm-picker">{{ inspectionOptions[inspectionIndex]?.label || '选择本次巡检' }} ▾</view></picker><text v-else class="sm-alert">当天尚无巡检。请先完成现场36项，保存成功后继续同页七类核对。</text><button v-if="!inspectionOptions.length" class="sm-btn" @click="openPage('/pages/station-safety-inspection/form')">开始现场巡检</button></view>
          <SafetyInspectionWorkflowEditor v-if="selectedInspection" :key="selectedInspection" ref="workflowEditor" :inspection-id="selectedInspection" :initial-category="workflowCategory" @saved="workflowSaved" @dirty="hasUnsavedChanges=$event" />
          <view v-if="daily.supplement?.items?.length" class="sm-card"><text class="sm-h3">此前保存的补充记录</text><text class="sm-help">历史补充保持原义。新流程按具体巡检记录事实，不把旧资料推定成本次已核查。</text><view v-for="item in daily.supplement.items.filter(item=>item.result_code)" :key="item.code" class="sm-list-row"><text class="sm-text">{{ item.code }} · {{ resultLabels[item.result_code] || item.result_code }}</text><text class="sm-help">{{ item.note || item.reason }}</text></view></view>
        </view>
        <view v-show="activeTab==='issues'" class="sm-stack"><view class="sm-card"><view class="sm-section-head"><text class="sm-h2">当天全部问题 · {{ snapshot.issues?.length || 0 }} 项</text><text class="sm-link" @click="openHazards">进入整改台账</text></view><text class="sm-help">按唯一隐患编号展示。复见关联同一问题，当天已整改和已关闭的问题仍保留。</text><view v-for="issue in snapshot.issues" :key="issue._id" class="sm-list-row"><text class="sm-h3">{{ issue.hazard_no || issue._id }} · {{ issue.hazard_level==='major'?'重大':'一般' }}</text><text class="sm-text">{{ issue.issue_note }}</text><text class="sm-help">责任人：{{ issue.responsible_name || '未填写' }} · 期限：{{ issue.planned_complete_date || '未填写' }} · {{ hazardStatus(issue.status) }}</text><text class="sm-text">整改要求：{{ issue.planned_measure || '未填写' }}</text></view><text v-if="!snapshot.issues?.length" class="sm-help">当前材料未发现当天问题；是否可以零报告仍需全部检查完成后核对。</text></view>
          <view class="sm-card"><text class="sm-h2">本次观察、上报与当场整改</text><view v-for="observation in snapshot.observations" :key="observation._id" class="sm-list-row"><text class="sm-h3">{{ observation.hazard_id }}</text><text class="sm-text">{{ observation.issue_note || observation.note }}</text><text class="sm-help">{{ formatDateTime(observation.discovered_at || observation.observed_at) }} · 临时措施：{{ observation.temporary_controls || '未记录' }}</text><text v-if="observation.report?.reported_at" class="sm-text">实际上报：{{ formatDateTime(observation.report.reported_at) }}，{{ observation.report.reported_to }}，{{ observation.report.method }}；{{ observation.report.requirements }}</text><text v-if="observation.on_site_rectification?.note" class="sm-text">当场整改：{{ observation.on_site_rectification.note }}；{{ formatDateTime(observation.on_site_rectification.completed_at) }}；复查：{{ observation.on_site_rectification.recheck_note }}</text></view><text v-if="!snapshot.observations?.length" class="sm-help">暂无另行登记的观察记录。</text></view>
          <view class="sm-card"><text class="sm-h2">历史待办 · {{ snapshot.historical_pending?.length || 0 }} 项</text><text class="sm-help">历史待办与当日新发现分别展示。仍存在未解决问题时不能确认零报告。</text><view v-for="issue in snapshot.historical_pending" :key="issue._id" class="sm-list-row"><text class="sm-h3">{{ issue.hazard_no || issue._id }}</text><text class="sm-text">{{ issue.issue_note }}</text><text class="sm-help">{{ issue.responsible_name }} · {{ issue.planned_complete_date }} · 截至 {{ issue.as_of_date || selectedDate }}：{{ hazardStatus(issue.status) }}<template v-if="issue.current_status"> · 当前：{{ hazardStatus(issue.current_status) }}</template><template v-if="issue.closure_time_unverified"> · 关闭时间证据待核验</template></text></view></view>
        </view>
        <view v-show="activeTab==='review'" class="sm-stack">
          <view v-if="hasUnsavedChanges" class="sm-alert">有尚未保存的七类核对，请先暂存，再核对日表。当前完整性依据已保存资料。</view><view class="sm-card"><text class="sm-h2">内容完整性</text><text v-if="snapshot.complete" class="sm-alert sm-alert--info">当天原巡检及七类核对内容齐全，可核对形成日表。</text><view v-else class="sm-alert"><text class="sm-text">待完成事项</text><text v-for="(missing,index) in snapshot.missing" :key="index" class="sm-text">• {{ missing }}</text></view><text class="sm-help">核对的是事实内容，签认状态始终为“待签认”。</text></view>
          <view class="sm-card"><text class="sm-h2">零报告确认</text><view class="sm-options sm-field"><view :class="['sm-option',{'sm-option--active':zeroReport===false}]" @click="zeroReport=false">不确认零报告</view><view :class="['sm-option',{'sm-option--active':zeroReport===true}]" @click="zeroReport=true">实际未发现问题，确认零报告</view></view><text class="sm-help">当天发现过问题、仍有历史未解决隐患或检查不完整时，服务端不允许确认零报告。</text></view>
          <view class="sm-card"><text class="sm-h2">台账核对与修订</text><text class="sm-text">{{ daily.record ? `已有核对版本 ${daily.record.revision} · ${formatDateTime(daily.record.checked_at)}` : '尚未形成已核对版本' }} · 待签认</text><text v-if="daily.record?.revision_reason" class="sm-help">上版说明：{{ daily.record.revision_reason }}</text><label class="sm-field"><text class="sm-field-label">{{ daily.record ? '本次修订原因 *' : '核对说明' }}</text><textarea v-model="revisionReason" class="sm-textarea" :disabled="!permissions.daily" placeholder="修订需写明新增、变更或更正的依据" /></label><button v-if="permissions.daily" class="sm-btn" :disabled="saving || !snapshot.complete || hasUnsavedChanges" @click="confirm">{{ saving?'保存中…':daily.record?'形成修订版并核对':'核对日表内容' }}</button><text class="sm-help">未保存的七类核对请先暂存。新增或更正来源后，日表会重新标记待核对，旧版保留。</text></view>
        </view>
        <SafetyRevisionHistory kind="daily" :record-id="daily.record?._id" title="日表修订历史" /><SafetyRevisionHistory kind="supplement" :record-id="daily.supplement?._id" title="补充检查修订历史" />
        <view class="sm-card sm-row"><button class="sm-btn sm-btn--secondary" @click="openSafetyPage('print',{kind:'daily',date:selectedDate})">打印预览 / 保存 PDF</button><button v-if="permissions.export" class="sm-btn sm-btn--secondary" :disabled="exporting" @click="exportExcel">{{ exporting?'正在生成…':'导出 Excel 明细' }}</button><button class="sm-btn sm-btn--secondary" @click="refreshSummary">刷新来源</button><text class="sm-help">打印和导出使用已保存资料；未保存的编辑不包含在导出中。</text></view>
      </template>
    </view>
  </SafetyManagementShell>
</template>
<script setup>
import { computed,onMounted,ref,watch,nextTick } from 'vue'
import SafetyManagementShell from './SafetyManagementShell.vue'
import SafetyInspectionWorkflowEditor from './SafetyInspectionWorkflowEditor.vue'
import SafetyRevisionHistory from './SafetyRevisionHistory.vue'
import { getSafetyDaily,confirmSafetyDaily,exportSafetyDocument } from '@/services/safetyManagement'
import { beijingDate,downloadFile,formatDateTime,openSafetyPage,openPage,openInspection,openHazards,resultLabels,categoryPending,categoryProgressText,showError } from './helpers'
const props=defineProps({date:{type:String,default:''}})
const selectedDate=ref(props.date || beijingDate()),loading=ref(true),saving=ref(false),exporting=ref(false),error=ref(''),daily=ref({}),activeTab=ref('sources'),revisionReason=ref(''),zeroReport=ref(false),selectedInspection=ref(''),workflowCategory=ref(1),workflowEditor=ref(null),hasUnsavedChanges=ref(false)
const tabs=[{key:'sources',label:'七类检查与原单'},{key:'supplement',label:'巡检内七类核对'},{key:'issues',label:'问题与历史待办'},{key:'review',label:'核对日表'}]
const snapshot=computed(()=>daily.value.snapshot || {}),permissions=computed(()=>daily.value.permissions || {})
const inspectionOptions=computed(()=>(snapshot.value.inspections || []).map(item=>({id:item._id,label:`${item.inspection_no} · ${item.inspector_name} · ${formatDateTime(item.ended_at || item.inspection_at)}`})))
const inspectionIndex=computed(()=>Math.max(0,inspectionOptions.value.findIndex(item=>item.id===selectedInspection.value)))
function checkStatus(check){if(check.missing?.length)return check.result_code==='abnormal'?'发现问题 · 待补依据':'待完成 · 缺少核对依据';if(check.covered_by_inspection)return `已引用 · ${resultLabels[check.result_code] || '待核实'}`;return resultLabels[check.result_code] || '待核实'}
function hazardStatus(value){return({pending_rectification:'待整改',pending_verification:'待复查',closed:'已复查销号',cancelled:'已取消'})[value] || value}
async function load(){loading.value=true;error.value='';try{daily.value=await getSafetyDaily({date:selectedDate.value});zeroReport.value=Boolean(daily.value.record?.zero_report);if(!inspectionOptions.value.some(item=>item.id===selectedInspection.value))selectedInspection.value=inspectionOptions.value[0]?.id || '';hasUnsavedChanges.value=false}catch(err){error.value=err.message}finally{loading.value=false}}
async function refreshSummary(){try{daily.value=await getSafetyDaily({date:selectedDate.value})}catch(err){showError(err)}}
async function workflowSaved(){hasUnsavedChanges.value=false;await refreshSummary()}
async function continueWorkflow(id,category=1){if(hasUnsavedChanges.value && id && id!==selectedInspection.value){showError(new Error('请先暂存当前巡检的七类核对，再切换记录'));return}selectedInspection.value=id || selectedInspection.value || inspectionOptions.value[0]?.id || '';workflowCategory.value=Number(category)||1;activeTab.value='supplement';await nextTick();workflowEditor.value?.focusCategory(workflowCategory.value);uni.pageScrollTo({scrollTop:0,duration:200})}
function chooseInspection(index){const id=inspectionOptions.value[index]?.id;if(id)continueWorkflow(id)}
async function confirm(){if(hasUnsavedChanges.value){showError(new Error('请先暂存巡检中的七类核对'));return}saving.value=true;try{await confirmSafetyDaily({date:selectedDate.value,expected_revision:daily.value.record?.revision || 0,source_fingerprint:snapshot.value.source_fingerprint,zero_report:zeroReport.value,revision_reason:revisionReason.value});revisionReason.value='';await refreshSummary();uni.showToast({title:'内容已核对，待签认',icon:'none'})}catch(err){showError(err)}finally{saving.value=false}}
async function exportExcel(){exporting.value=true;try{downloadFile(await exportSafetyDocument({kind:'daily',date:selectedDate.value,format:'xlsx'}))}catch(err){showError(err)}finally{exporting.value=false}}
async function changeDate(date){if(date===selectedDate.value)return;const change=async()=>{selectedDate.value=date;revisionReason.value='';await load()};if(!hasUnsavedChanges.value)return change();uni.showModal({title:'切换日期',content:'七类核对还有未保存编辑，切换后不保留。确认切换吗？',success:result=>{if(result.confirm)change()}})}
watch(()=>props.date,date=>{if(date&&date!==selectedDate.value){selectedDate.value=date;load()}})
onMounted(load)
</script>
